// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address depositor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, type(uint128).max);

        vm.deal(depositor, amount * 2);

        vm.prank(depositor);
        (bool ok1, ) = address(c).call{value: amount}("");
        assertTrue(ok1);

        uint256 afterFirst = c.depositsCount();

        vm.prank(depositor);
        (bool ok2, ) = address(c).call{value: amount}("");
        assertTrue(ok2);

        uint256 afterSecond = c.depositsCount();

        // General rule: every accepted deposit increments depositsCount by exactly one.
        assertTrue(afterFirst == 1 && afterSecond == afterFirst + 1);
    }
}
